package main

import (
	"fmt"
)

func gcd(x, y int) int {
	for y != 0 {
		x, y = y, x%y
	}
	return x
}

func main() {
	var a, b, n int
	fmt.Scan(&a, &b, &n)

	for {
		ax := gcd(a, n)
		if ax > n {
			fmt.Println(1)
			return
		}
		n -= ax
		bx := gcd(b, n)
		if bx > n {
			fmt.Println(0)
			return
		}
		n -= bx
	}
}

